# Pièces supplémentaires des dossiers d'enquête « Vivre ensemble (EMC) » : une par enquête + leur question (primaire qp, collège qc).
# Tout personnage inventé est signalé « Personnage fictif » dans src ; les modèles de documents, « Reconstitution pédagogique ».
def Q(q, a): return {'k': 'qcm', 'q': q, 'a': a}
def V(q, ok): return {'k': 'vf', 'q': q, 'a': ok}
def W(q, m): return {'k': 'libre', 'q': q, 'm': m}

X = {
'emc-0': dict(kind='fiche', t='Fiche : ce que dit la Constitution (article 2)', src='Fiche de l’atlas, d’après l’article 2 de la Constitution de 1958 (cité exactement).',
 txt="L'article 2 de la Constitution de 1958 dit : « La langue de la République est le français. L'emblème national est le drapeau tricolore, bleu, blanc, rouge. L'hymne national est \"La Marseillaise\". La devise de la République est \"Liberté, Égalité, Fraternité\". Son principe est : gouvernement du peuple, par le peuple et pour le peuple. »\nLe 14 Juillet est la fête nationale depuis une loi de 1880.\nMarianne n'est pas citée dans la Constitution, mais son buste se trouve dans presque toutes les mairies.",
 qp=Q('D’après la Constitution, quelle est la langue de la République ?', ['Le français', 'L’anglais', 'Le latin']),
 qc=W('Que veut dire « gouvernement du peuple, par le peuple et pour le peuple » ?', 'Le pouvoir appartient aux citoyens : ils choisissent leurs représentants par le vote, et les décisions doivent servir l’intérêt de tous.')),
'emc-1': dict(kind='formulaire', t='Carte électorale (modèle simplifié)', src='Reconstitution pédagogique : modèle simplifié inspiré de la carte électorale française ; ce n’est pas un vrai document et l’électrice est inventée.',
 fields=[('Nom', 'MARTIN'), ('Prénom', 'Lina'), ('Date de naissance', '12 mars 2008'), ('Commune', 'Pouembout'), ('Bureau de vote', 'n° 1 · école'),
         ('Numéro d’électeur', '0427'), ('Elle pourra voter', 'municipales, législatives, présidentielle ; provinciales si elle est inscrite sur la liste électorale spéciale')],
 qp=Q('Lina est née en 2008. En quelle année a-t-elle eu le droit de voter ?', ['En 2026, à 18 ans', 'En 2018, à 10 ans', 'En 2038, à 30 ans']),
 qc=W('À quoi sert la carte électorale ?', 'Elle montre qu’on est inscrit sur la liste électorale d’une commune et indique le bureau où l’on vote ; on peut la présenter le jour du vote, avec une pièce d’identité.')),
'emc-2': dict(kind='fiche', t='Fiche : comment naît une loi du pays ?', src='Fiche de l’atlas, d’après la loi organique de 1999 (simplifiée).',
 txt="1. Le gouvernement de la Nouvelle-Calédonie, ou des membres du Congrès, proposent un texte.\n2. Le Conseil d'État donne son avis. Si le texte touche à l'identité kanak (coutume, terres coutumières, signes identitaires…), le Sénat coutumier est consulté.\n3. Le Congrès discute le texte et le vote.\n4. Avant sa publication, le texte peut être contrôlé par le Conseil constitutionnel.\n5. La loi du pays est publiée au Journal officiel de la Nouvelle-Calédonie : elle s'applique.",
 qp=V('C’est le Congrès qui vote les lois du pays.', True),
 qc=W('Pourquoi consulte-t-on le Sénat coutumier pour certaines lois du pays ?', 'Parce qu’elles touchent à l’identité kanak (coutume, terres coutumières, signes identitaires) : il faut l’avis des représentants des aires coutumières.')),
'emc-3': dict(kind='lettre', t='Lettre d’une électrice, avril 1945', src='Personnage fictif. Lettre imaginée d’après les récits des élections municipales du 29 avril 1945, les premières où les Françaises ont voté.',
 txt="Ma chère Suzanne,\nDimanche 29 avril, aux élections municipales, j'ai voté pour la première fois de ma vie ! Ta grand-mère est venue avec moi : à soixante-dix ans, elle n'avait jamais mis un bulletin dans l'urne. Il y avait la queue devant l'école. Certains hommes riaient, d'autres nous ont saluées.\nJ'ai pensé à toutes celles qui se sont battues pour ce droit. Quand tu auras vingt et un ans, tu voteras aussi.\nTa tante Jeanne",
 qp=Q('À quelle élection Jeanne vote-t-elle pour la première fois ?', ['Aux élections municipales d’avril 1945', 'À une élection présidentielle', 'Au vote de 1848']),
 qc=W('Cette lettre est inventée. Qu’apporte-t-elle quand même à l’enquête ?', 'Elle s’appuie sur des faits réels (premier vote des Françaises aux municipales du 29 avril 1945, vote à 21 ans) et fait comprendre ce que ce moment représentait ; mais ce n’est pas un vrai témoignage.')),
'emc-4': dict(kind='fiche', t='Fiche : le Code noir (1685)', src='Fiche de l’atlas, d’après l’édit royal de mars 1685.',
 txt="En 1685, sous Louis XIV, un édit du roi, appelé plus tard le « Code noir », fixe les règles de l'esclavage dans les colonies françaises des Antilles.\nIl considère les esclaves comme des biens : on peut les vendre, les acheter, les transmettre en héritage.\nIl prévoit des punitions très dures contre ceux qui s'enfuient.\nCe texte reste appliqué, avec des modifications, jusqu'à l'abolition de 1848.",
 qp=V('Le Code noir considérait les esclaves comme des biens que l’on pouvait vendre.', True),
 qc=W('Pourquoi le Code noir montre-t-il que l’esclavage était organisé par l’État ?', 'C’est un texte du roi, une loi officielle : l’État fixait lui-même les règles de l’esclavage dans ses colonies.')),
'emc-5': dict(kind='carnet', t='Carnet d’une déléguée de classe', src='Personnage fictif. Situation imaginée pour l’atlas ; les articles de la Convention cités sont réels.',
 txt="Lundi. Au conseil des élèves, on a parlé de la cour : les petits n'osent pas jouer au ballon. J'ai rappelé l'article 31 de la Convention : tous les enfants ont le droit de jouer.\nMardi. Proposition votée : un coin ballon le lundi et le jeudi pour les CP et les CE1.\nVendredi. La maîtresse dit que l'article 12 est respecté : on nous a demandé notre avis, et on en a tenu compte.",
 qp=Q('Quel droit la déléguée rappelle-t-elle ?', ['Le droit de jouer', 'Le droit de conduire', 'Le droit de voter']),
 qc=W('Comment cette situation montre-t-elle que l’article 12 est respecté ?', 'Les élèves ont donné leur avis au conseil des élèves, ils ont voté une proposition, et les adultes en ont tenu compte.')),
'emc-6': dict(kind='fiche', t='Fiche : la Charte de la laïcité à l’école (France, 2013), quelques articles', src='Résumé de l’atlas : ce n’est pas le texte original. Cette charte a été écrite pour les écoles publiques de France ; en Nouvelle-Calédonie, la loi de 2004 sur les signes religieux ne visait que les collèges et lycées de l’État.',
 txt="Article 1 : la France est une République indivisible, laïque, démocratique et sociale.\nArticle 3 : la laïcité garantit à tous la liberté de conscience : chacun est libre de croire ou de ne pas croire.\nArticle 9 : la laïcité refuse toutes les violences et toutes les discriminations ; elle garantit l'égalité entre les filles et les garçons.\nArticle 12 : aucun sujet n'est exclu du questionnement scientifique et pédagogique.\nArticle 14 : à l'école publique, les élèves ne portent pas de signes ou de tenues montrant de façon ostensible une appartenance religieuse.",
 qp=V('D’après la Charte, chacun est libre de croire ou de ne pas croire.', True),
 qc=W('Pourquoi la laïcité garantit-elle aussi l’égalité entre les filles et les garçons ?', 'Parce qu’elle refuse les discriminations : à l’école publique, tous les élèves ont les mêmes droits et suivent les mêmes enseignements, quelles que soient leurs croyances.')),
'emc-7': dict(kind='fiche', t='Fiche : l’accord FRANZ (1992)', src='Fiche de l’atlas.',
 txt="Signé en 1992 par la France, l'Australie et la Nouvelle-Zélande, l'accord FRANZ sert à coordonner l'aide aux pays du Pacifique Sud frappés par une catastrophe naturelle.\nQuand un pays touché demande de l'aide, les trois partenaires se répartissent le travail : reconnaissance par avion, transport d'eau potable, de bâches, de nourriture et de médicaments, réparation des réseaux.\nLa France intervient surtout depuis la Nouvelle-Calédonie et la Polynésie française, avec ses avions et ses navires militaires.",
 qp=Q('Quels pays ont signé l’accord FRANZ ?', ['La France, l’Australie et la Nouvelle-Zélande', 'La France et le Japon', 'Les États-Unis et la Chine']),
 qc=W('Pourquoi l’aide n’arrive-t-elle que si le pays touché la demande ?', 'Parce que chaque pays est souverain : on respecte sa décision et on répond à ses besoins réels, sans s’imposer.')),
}
